        if (L.type === "overlay" || L.type === "fx" || L.hidden) continue;
        if (localT < st - 0.01 || localT > st + du + 0.01) continue;
        const r = L.rect ?? { x: 0, y: 0, w: S.ir.width, h: S.ir.height };
        const d = renderedDelta(L, si);
